package cn.binbin.crm;
import java.time.*;import java.util.*;import java.util.function.*;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.support.TransactionTemplate;
import static cn.binbin.crm.TradeService.*;
@Service
public class P3Base {
 static Map<String,Object> map(Object... values){var p=SaasService.parameters(values);p.replaceAll((k,v)->v instanceof Instant t?java.sql.Timestamp.from(t):v);return p;}
 final NamedParameterJdbcTemplate db;final TransactionTemplate tx;final AuthService auth;final TradeService data;final CustomerService customers;final BusinessService business;final SalesService sales;
 public P3Base(NamedParameterJdbcTemplate db,TransactionTemplate tx,AuthService auth,TradeService data,CustomerService customers,BusinessService business,SalesService sales){this.db=db;this.tx=tx;this.auth=auth;this.data=data;this.customers=customers;this.business=business;this.sales=sales;}
 <T>T scoped(AuthService.Session s,String module,boolean write,Function<AuthService.Actor,T> fn){return tx.execute(status->{if(write&&s.tenantId()!=null)db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",s.tenantId()),UUID.class);var a=auth.actor(s);if(a.supportGrantId()!=null)throw ApiError.forbidden("支持授权不含服务、知识、营销与集成");var p=a.p3Access();boolean ok=switch(module){case "ticket"->p.tickets().read()&&(!write||p.tickets().write());case "sla"->p.tickets().read()&&(!write||p.slaManage());case "knowledge"->p.knowledgeRead()&&(!write||p.knowledgeWrite());case "publish"->p.knowledgePublish();case "campaign"->p.campaigns().read()&&(!write||p.campaigns().write());case "launch"->p.campaignLaunch();case "integration"->p.integrationRead()&&(!write||p.integrationManage());case "export-ticket"->p.tickets().read()&&p.export();case "export-campaign"->p.campaigns().read()&&p.export();default->false;};if(!ok)throw ApiError.forbidden("当前角色没有该 P3 模块权限");if(write&&!a.tenant().subscriptionEnd().isAfter(Instant.now()))throw ApiError.forbidden("订阅到期，当前只可查看");context(a.tenant().id());return fn.apply(a);});}
 void context(UUID tenant){db.queryForObject("SELECT set_config('crm.tenant_id',:tenant,true)",map("tenant",tenant.toString()),String.class);}
 Map<String,Object> params(AuthService.Actor a){var p=data.params(a);for(var entry:Map.of("ticket",a.p3Access().tickets(),"campaign",a.p3Access().campaigns()).entrySet()){var s=entry.getValue();String k=entry.getKey();p.put(k+"Reader",s.read());p.put(k+"Writer",s.write()&&a.tenant().subscriptionEnd().isAfter(Instant.now()));p.put(k+"ReadAll",s.readAll());p.put(k+"ReadDepartment",s.readDepartment());p.put(k+"WriteAll",s.writeAll());p.put(k+"WriteDepartment",s.writeDepartment());}return p;}
 static String own(String module,String row,String member,boolean write){return "(:"+module+(write?"WriteAll":"ReadAll")+" OR "+row+".owner_member_id=:member OR (:"+module+(write?"WriteDepartment":"ReadDepartment")+" AND "+member+".department_id=:department))";}
 List<Map<String,Object>> rows(String sql,Map<String,?> p){var rows=data.rows(sql,p);for(var row:rows)row.replaceAll((k,v)->{if(v!=null&&Set.of("targets","slaSnapshot","scopes","events","payload").contains(k)&&!(v instanceof Map)&&!(v instanceof List))try{return data.json.readValue(String.valueOf(v),Object.class);}catch(Exception e){throw new IllegalStateException("P3 JSON metadata invalid");}return v;});return rows;}Map<String,Object> one(String sql,Map<String,?> p){var rows=rows(sql,p);if(rows.isEmpty())throw ApiError.missing();return rows.getFirst();}String json(Object value){return data.body(value);}Map<String,Object> object(String value){return data.object(value);}
 UUID once(AuthService.Actor a,String op,String key,Object body,Supplier<UUID> fn){return data.once(a,op,key,body,fn);}void audit(AuthService.Actor a,String action,String entity,UUID id,long version,UUID trace){data.audit(a,action,entity,id,version,trace);}
 AuthService.Actor actor(UUID tenant,UUID member){var u=one("SELECT u.*,m.id AS member_id FROM sys_tenant_member m JOIN iam_user u ON u.id=m.user_id WHERE m.tenant_id=:tenant AND m.id=:member AND m.status='ACTIVE' AND u.status='ACTIVE' AND NOT u.must_change_password",map("tenant",tenant,"member",member));return auth.actor(new AuthService.Session(UUID.randomUUID(),(UUID)u.get("id"),(String)u.get("username"),(String)u.get("displayName"),Boolean.TRUE.equals(u.get("isPlatformOperator")),"",tenant,Instant.now().plusSeconds(3600),false,null));}
 List<Map<String,Object>> memberOptions(AuthService.Actor a,String module){var p=params(a);var scope=module.equals("ticket")?a.p3Access().tickets():a.p3Access().campaigns();p.put("allScope",scope.writeAll());p.put("deptScope",scope.writeDepartment());return rows("SELECT m.id,m.display_name AS name FROM sys_tenant_member m JOIN iam_user u ON u.id=m.user_id WHERE m.tenant_id=:tenant AND m.status='ACTIVE' AND u.status='ACTIVE' AND NOT u.must_change_password AND (:allScope OR m.id=:member OR (:deptScope AND m.department_id=:department)) ORDER BY m.display_name,m.id",p).stream().filter(m->{try{var candidate=actor(a.tenant().id(),(UUID)m.get("id"));return module.equals("ticket")?candidate.p3Access().tickets().write():candidate.businessAccess().tasks().read();}catch(ApiError e){return false;}}).toList();}
 void customer(AuthService.Actor a,UUID id,boolean write){if(id==null)return;if(!a.canReadCustomers())throw ApiError.forbidden("关联客户需要客户读取权限");var c=customers.get(a,id);if(write&&!c.canWrite())throw ApiError.forbidden("没有关联客户写入权限");}
 void version(Map<String,Object> row,long expected){if(number(row,"version")!=expected)throw ApiError.conflict("记录已变化，请刷新");}
}
